import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`social-media-manager`,heroTitle:`Plan a week of content in minutes`,heroSubtitle:`Perplexity Computer learns your brand voice, finds trending formats in your niche, and generates 7 days of platform-native posts automatically.`,inputUrlCta:`Build my content calendar`,inputUrlPlaceholder:`yourbrand.com`,inputUrlPrefill:`Go to {url} and perform a deep brand voice analysis — extract tone, messaging pillars, target audience, visual style, and key themes. Then do the following: 1) Research trending topics, formats, and hooks in the brand's niche across TikTok, Instagram Reels, Twitter/X, LinkedIn, and Facebook — including trending sounds, thread formats, carousel styles, and hashtag clusters. 2) Generate a full 7-day content calendar with platform-native posts for each channel. Each post should include: a scroll-stopping hook, full caption, relevant hashtags (5-10 per post), a CTA, and an image or video prompt describing the visual creative. 3) Tailor every post to the brand voice extracted in step one — same tone, language patterns, and messaging pillars. 4) Organize the calendar by day and platform in a clean table format, with columns for date, platform, post type, hook, caption, hashtags, CTA, and image or video prompt. 5) Include a brief trend report explaining why each topic or format was chosen and its current engagement trajectory. Export the full calendar to Google Sheets or provide a structured output ready to paste into Buffer, Later, or Notion.`,heroOverlaySteps:[`Studying your site for brand voice, tone, and audience`,`Scanning trending topics and formats across TikTok, Instagram, and X`,`Generating 7 days of platform-native posts in your brand voice`,`Content calendar with captions, hooks, and hashtags ready to schedule`],generatingSteps:[`Visiting {url} to extract brand voice, tone, and messaging pillars`,`Designing an agent to research trending topics and formats across social platforms`,`Configuring platform-native post generation with hooks, captions, and image prompts`,`Setting up your 7-day content calendar with export and scheduling options`],featureSectionTitle:`From URL to a week of content`,featureCardTitles:[`The best model for every task`,`Connects to your content stack`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Notion, Canva, Slack, Google Drive — Computer builds your calendar and pushes it straight into the tools you already use.`,`Platform-native captions. Scroll-stopping hooks. Hashtag clusters. Image and video prompts. A complete 7-day calendar ready to publish.`],capabilitySectionTitle:`Your content team, on autopilot`,capabilitySectionSubtitle:`Paste your URL, step away, come back to a week of ready-to-post content.`,capabilityCards:[{title:`Brand Voice Training`,description:`Computer can study your website, guidelines, and past content — then write every post in your exact tone, language, and style.`},{title:`Trend Research`,description:`Computer can scan TikTok, Instagram, X, and LinkedIn for trending topics, sounds, and formats in your niche — and match them to your brand.`},{title:`Platform-Native Posts`,description:`Computer can generate scroll-stopping hooks, captions, hashtags, CTAs, and creative briefs tailored to each platform's algorithm and audience.`},{title:`Connect Your Tools`,description:`Computer can export to Google Sheets, Notion, Canva, Slack, and Google Drive — build workflows across your entire content stack.`},{title:`Remember & Improve`,description:`Computer can remember your brand voice, past calendars, and top-performing posts so every week's content gets sharper.`},{title:`Monitor & Alert`,description:`Computer can track emerging trends in your niche weekly and flag new content opportunities before your competitors catch on.`}]});export{t as default};
